19	func GetExternalModuleIndicatorOptions(fileName string, options *core.CompilerOptions, metadata SourceFileMetaData) ExternalModuleIndicatorOptions {
20		if tspath.IsDeclarationFileName(fileName) {
21			return ExternalModuleIndicatorOptions{}
22		}
23	
24		switch options.GetEmitModuleDetectionKind() {
25		case core.ModuleDetectionKindForce:
26			// All non-declaration files are modules, declaration files still do the usual isFileProbablyExternalModule
27			return ExternalModuleIndicatorOptions{Force: true}
28		case core.ModuleDetectionKindLegacy:
29			// Files are modules if they have imports, exports, or import.meta
30			return ExternalModuleIndicatorOptions{}
31		case core.ModuleDetectionKindAuto:
32			// If module is nodenext or node16, all esm format files are modules
33			// If jsx is react-jsx or react-jsxdev then jsx tags force module-ness
34			// otherwise, the presence of import or export statments (or import.meta) implies module-ness
35			return ExternalModuleIndicatorOptions{
36				JSX:   options.Jsx == core.JsxEmitReactJSX || options.Jsx == core.JsxEmitReactJSXDev,
37				Force: isFileForcedToBeModuleByFormat(fileName, options, metadata),
38			}
39		default:
40			return ExternalModuleIndicatorOptions{}
41		}
42	}
