46	func isFileForcedToBeModuleByFormat(fileName string, options *core.CompilerOptions, metadata SourceFileMetaData) bool {
47		// Excludes declaration files - they still require an explicit `export {}` or the like
48		// for back compat purposes. The only non-declaration files _not_ forced to be a module are `.js` files
49		// that aren't esm-mode (meaning not in a `type: module` scope).
50		if GetImpliedNodeFormatForEmitWorker(fileName, options.GetEmitModuleKind(), metadata) == core.ModuleKindESNext || tspath.FileExtensionIsOneOf(fileName, isFileForcedToBeModuleByFormatExtensions) {
51			return true
52		}
53		return false
54	}
