61		if file.ScriptKind == core.ScriptKindJSON {
62			return nil
63		}
64	
65		if node := isFileProbablyExternalModule(file); node != nil {
66			return node
67		}
68	
69		if file.IsDeclarationFile {
70			return nil
71		}
72	
73		if opts.JSX {
74			if node := isFileModuleFromUsingJSXTag(file); node != nil {
75				return node
76			}
77		}
78	
79		if opts.Force {
80			return file.AsNode()
81		}
82	
83		return nil
84	}
