86	func isFileProbablyExternalModule(sourceFile *SourceFile) *Node {
87		for _, statement := range sourceFile.Statements.Nodes {
88			if isAnExternalModuleIndicatorNode(statement) {
89				return statement
90			}
91		}
92		return getImportMetaIfNecessary(sourceFile)
93	}
