95	func isAnExternalModuleIndicatorNode(node *Node) bool {
96		return HasSyntacticModifier(node, ModifierFlagsExport) ||
97			IsImportEqualsDeclaration(node) && IsExternalModuleReference(node.AsImportEqualsDeclaration().ModuleReference) ||
98			IsImportDeclaration(node) || IsExportAssignment(node) || IsExportDeclaration(node)
99	}
