101	func getImportMetaIfNecessary(sourceFile *SourceFile) *Node {
102		if sourceFile.AsNode().Flags&NodeFlagsPossiblyContainsImportMeta != 0 {
103			return findChildNode(sourceFile.AsNode(), IsImportMeta)
104		}
105		return nil
106	}
