108	func findChildNode(root *Node, check func(*Node) bool) *Node {
109		var result *Node
110		var visit func(*Node) bool
111		visit = func(node *Node) bool {
112			if check(node) {
113				result = node
114				return true
115			}
116			return node.ForEachChild(visit)
117		}
118		visit(root)
119		return result
120	}
121	
122	func isFileModuleFromUsingJSXTag(file *SourceFile) *Node {
123		return walkTreeForJSXTags(file.AsNode())
124	}
125	
126	// This is a somewhat unavoidable full tree walk to locate a JSX tag - `import.meta` requires the same,
127	// but we avoid that walk (or parts of it) if at all possible using the `PossiblyContainsImportMeta` node flag.
128	// Unfortunately, there's no `NodeFlag` space to do the same for JSX.
129	func walkTreeForJSXTags(node *Node) *Node {
130		var found *Node
131	
132		var visitor func(node *Node) bool
133		visitor = func(node *Node) bool {
134			if found != nil {
135				return true
136			}
137			if node.SubtreeFacts()&SubtreeContainsJsx == 0 {
138				return false
139			}
140			if IsJsxOpeningLikeElement(node) || IsJsxFragment(node) {
141				found = node
142				return true
143			}
144			return node.ForEachChild(visitor)
145		}
146		visitor(node)
147	
148		return found
